const ee = require('@google/earthengine');
const privateKey = require('../auth_keys/test-project-473922-29f05d49bed7');

async function runAnalysis() {
  // 1. Geometry & Time Definitions
  const aswanDam = ee.Geometry.Point([32.88, 23.97]).buffer(10000); // 10km buffer
  const ethiopiaDam = ee.Geometry.Point([35.09, 11.21]).buffer(10000); // 10km buffer
  const startDate = '2016-01-01';
  const endDate = '2016-12-31';

  // 2. Data Acquisition - VIIRS Nighttime Lights
  const viirsCol = ee.ImageCollection('NOAA/VIIRS/DNB/MONTHLY_V1/VCMCFG')
    .filterDate(startDate, endDate)
    .select('avg_rad');

  // Check collection size
  const colSize = viirsCol.size().getInfo();
  if (colSize === 0) {
    print("No VIIRS nighttime data found for 2016.");
    print("<answer>C1</answer>");
    return;
  }

  // Create composite for the year
  const composite = viirsCol.mean();

  // 3. Processing - Calculate mean brightness for both locations
  const aswanStats = composite.reduceRegion({
    reducer: ee.Reducer.mean().combine({
      reducer2: ee.Reducer.count(),
      sharedInputs: true
    }),
    geometry: aswanDam,
    scale: 1000,
    maxPixels: 1e9
  });

  const ethiopiaStats = composite.reduceRegion({
    reducer: ee.Reducer.mean().combine({
      reducer2: ee.Reducer.count(),
      sharedInputs: true
    }),
    geometry: ethiopiaDam,
    scale: 1000,
    maxPixels: 1e9
  });

  const aswanMean = aswanStats.get('avg_rad_mean').getInfo();
  const aswanCount = aswanStats.get('avg_rad_count').getInfo();
  const ethiopiaMean = ethiopiaStats.get('avg_rad_mean').getInfo();
  const ethiopiaCount = ethiopiaStats.get('avg_rad_count').getInfo();

  // 4. Check for valid pixels
  if (aswanCount === 0 || ethiopiaCount === 0) {
    print(`Aswan pixels: ${aswanCount}, Ethiopia pixels: ${ethiopiaCount}`);
    print("<answer>C2</answer>");
    return;
  }

  // 5. Validation & Final Answer
  print(`Aswan brightness: ${aswanMean?.toFixed(2)}, Pixels: ${aswanCount}`);
  print(`Ethiopia brightness: ${ethiopiaMean?.toFixed(2)}, Pixels: ${ethiopiaCount}`);

  if (aswanMean === null || ethiopiaMean === null || 
      isNaN(aswanMean) || isNaN(ethiopiaMean)) {
    print("<answer>C3</answer>");
  } else if (aswanMean > ethiopiaMean) {
    print("<answer>A</answer>");
  } else {
    print("<answer>B</answer>");
  }
}

async function initEE() {
  await new Promise((resolve, reject) => {
    ee.data.authenticateViaPrivateKey(privateKey, resolve, reject);
  });
  await new Promise((resolve, reject) => {
    ee.initialize(null, null, resolve, reject);
  });
  await runAnalysis();
}

initEE();
